func thresholdDetectionValidateConfiguredExceptionList(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value thresholdDetectionWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > thresholdDetectionExceptionListMaxItems {
		diagnostics.AddError("Invalid threshold detection exception_list", fmt.Sprintf("exception_list may contain at most %d item blocks.", thresholdDetectionExceptionListMaxItems))
		return diagnostics
	}
	var items []thresholdDetectionExceptionListItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("exception_list item %d", index+1)
		if item.ConcatenateType.IsNull() {
			diagnostics.AddError("Invalid threshold detection item", location+" concatenate_type is required.")
		} else if !item.ConcatenateType.IsUnknown() {
			thresholdDetectionValidateString(location, " concatenate_type", item.ConcatenateType.ValueString(), 0, 0, &diagnostics)
			if !thresholdDetectionExceptionListConcatenateTypeValid(item.ConcatenateType.ValueString()) {
				diagnostics.AddError("Invalid threshold detection item", location+" concatenate_type must be one of AND, OR.")
			}
		}
		if !item.IpRange.IsNull() && !item.IpRange.IsUnknown() {
		}
		if item.MatchTarget.IsNull() {
			diagnostics.AddError("Invalid threshold detection item", location+" match_target is required.")
		} else if !item.MatchTarget.IsUnknown() {
			thresholdDetectionValidateString(location, " match_target", item.MatchTarget.ValueString(), 0, 0, &diagnostics)
			if !thresholdDetectionExceptionListMatchTargetValid(item.MatchTarget.ValueString()) {
				diagnostics.AddError("Invalid threshold detection item", location+" match_target must be one of CLIENT_IP, COOKIE, FULL_URL, HOST, PARAMETER, URI.")
			}
		}
		if item.Operator.IsNull() {
			diagnostics.AddError("Invalid threshold detection item", location+" operator is required.")
		} else if !item.Operator.IsUnknown() {
			thresholdDetectionValidateString(location, " operator", item.Operator.ValueString(), 0, 0, &diagnostics)
			if !thresholdDetectionExceptionListOperatorValid(item.Operator.ValueString()) {
				diagnostics.AddError("Invalid threshold detection item", location+" operator must be one of EQ, NE, REGEXP_MATCH, STRING_MATCH.")
			}
		}
		if !item.Value.IsNull() && !item.Value.IsUnknown() {
		}
		if !item.ValueName.IsNull() && !item.ValueName.IsUnknown() {
		}
	}
	return diagnostics
}

func thresholdDetectionBuildConfiguredExceptionList(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (thresholdDetectionExceptionListOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown threshold detection exception_list", "The exception_list ownership wrapper must be known during apply.")
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown threshold detection exception_list", "The planned exception_list ownership wrapper must be known during apply.")
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper thresholdDetectionWrapperModel
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown threshold detection exception_list", "The exception_list item blocks must be known during apply.")
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return thresholdDetectionExceptionListOwnedList{Set: true, Items: []thresholdDetectionExceptionListWireItem{}}, diagnostics
	}

	var configItems, planItems []thresholdDetectionExceptionListItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid threshold detection exception_list", "The planned item list unexpectedly became null.")
		}
		return thresholdDetectionExceptionListOwnedList{Set: true, Items: []thresholdDetectionExceptionListWireItem{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid threshold detection exception_list", "Configured and planned item counts differ.")
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}
	if len(configItems) > thresholdDetectionExceptionListMaxItems {
		diagnostics.AddError("Invalid threshold detection exception_list", fmt.Sprintf("exception_list may contain at most %d item blocks.", thresholdDetectionExceptionListMaxItems))
		return thresholdDetectionExceptionListOwnedList{}, diagnostics
	}

	items := make([]thresholdDetectionExceptionListWireItem, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("exception_list item %d", index+1)
		item := thresholdDetectionExceptionListWireItem{
			Index: index + 1,
		}
		concatenate_typeValue, ok := thresholdDetectionPlannedRequiredString(configuredItem.ConcatenateType, plannedItem.ConcatenateType, location+" concatenate_type", &diagnostics)
		if !ok {
			continue
		}
		thresholdDetectionValidateString(location, " concatenate_type", concatenate_typeValue, 0, 0, &diagnostics)
		if !thresholdDetectionExceptionListConcatenateTypeValid(concatenate_typeValue) {
			diagnostics.AddError("Invalid threshold detection item", location+" concatenate_type must be one of AND, OR.")
		}
		item.ConcatenateType = concatenate_typeValue
		item.IpRange = thresholdDetectionPlannedOptionalString(configuredItem.IpRange, plannedItem.IpRange, location+" ip_range", 0, &diagnostics)
		match_targetValue, ok := thresholdDetectionPlannedRequiredString(configuredItem.MatchTarget, plannedItem.MatchTarget, location+" match_target", &diagnostics)
		if !ok {
			continue
		}
		thresholdDetectionValidateString(location, " match_target", match_targetValue, 0, 0, &diagnostics)
		if !thresholdDetectionExceptionListMatchTargetValid(match_targetValue) {
			diagnostics.AddError("Invalid threshold detection item", location+" match_target must be one of CLIENT_IP, COOKIE, FULL_URL, HOST, PARAMETER, URI.")
		}
		item.MatchTarget = match_targetValue
		operatorValue, ok := thresholdDetectionPlannedRequiredString(configuredItem.Operator, plannedItem.Operator, location+" operator", &diagnostics)
		if !ok {
			continue
		}
		thresholdDetectionValidateString(location, " operator", operatorValue, 0, 0, &diagnostics)
		if !thresholdDetectionExceptionListOperatorValid(operatorValue) {
			diagnostics.AddError("Invalid threshold detection item", location+" operator must be one of EQ, NE, REGEXP_MATCH, STRING_MATCH.")
		}
		item.Operator = operatorValue
		item.Value = thresholdDetectionPlannedOptionalString(configuredItem.Value, plannedItem.Value, location+" value", 0, &diagnostics)
		value_checkValue, ok := thresholdDetectionPlannedBool(configuredItem.ValueCheck, plannedItem.ValueCheck, location+" value_check", false, &diagnostics)
		if !ok {
			continue
		}
		item.ValueCheck = value_checkValue
		item.ValueName = thresholdDetectionPlannedOptionalString(configuredItem.ValueName, plannedItem.ValueName, location+" value_name", 0, &diagnostics)
		items = append(items, item)
	}
	return thresholdDetectionExceptionListOwnedList{Set: true, Items: items}, diagnostics
}
